INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "蜀将刘知俊任都招讨使而诸旧将多不奉令。", "citation": "卷270·贞明三年（917）·zztj-v270-y0917-p013·原文件第18行", "note": "原文：蜀主以刘知俊为都招讨使，诸将皆旧功臣，多不用其命，且疾之，故无成功。；核对说明：“无成功”是主书对本次任用的评价，不概括刘知俊终生战绩。", "status": "draft", "id": "b0999506-c5a1-599a-bce5-e506f9162d38", "subject_id": "91fd1cff-abb3-586d-ab62-96656f754940", "source_id": "1edebe08-bb9d-5c2e-b608-fc232fd96621"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "917年十二月以前的军事局势；起日未载", "citation": "卷270·贞明三年（917）·zztj-v270-y0917-p013·原文件第18行", "note": "原文：蜀主以刘知俊为都招讨使，诸将皆旧功臣，多不用其命，且疾之，故无成功。；核对说明：只保留原纪年，不换算公历日；叙述性回顾不推成逐次日期。", "status": "draft", "id": "730d1bd0-9c28-5b77-a9f1-693029117cb1", "subject_id": "91fd1cff-abb3-586d-ab62-96656f754940", "source_id": "1edebe08-bb9d-5c2e-b608-fc232fd96621"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记王建：任刘知俊为都招讨使者。", "citation": "卷270·贞明三年（917）·zztj-v270-y0917-p013·原文件第18行", "note": "原文：蜀主以刘知俊为都招讨使，诸将皆旧功臣，多不用其命，且疾之，故无成功。；核对说明：原文称谓与既有姓名合并；原文摘录保留底本字形。", "status": "draft", "id": "6e7b04b4-1180-5998-849c-607ccee36290", "subject_id": "b02193d6-1c17-5154-bb7c-3295ed8dbbec", "source_id": "1edebe08-bb9d-5c2e-b608-fc232fd96621"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "蜀主：任刘知俊为都招讨使者。", "citation": "卷270·贞明三年（917）·zztj-v270-y0917-p013·原文件第18行", "note": "原文：蜀主以刘知俊为都招讨使，诸将皆旧功臣，多不用其命，且疾之，故无成功。；核对说明：参与身份依据本句；称谓按既有主体匹配。", "status": "draft", "id": "feddfac3-0f03-5be3-acd3-aa1cd8b309c5", "subject_id": "50ce6a48-2406-5abc-b730-7b1301cca818", "source_id": "1edebe08-bb9d-5c2e-b608-fc232fd96621"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记刘知俊：因旧将不奉令而未获战功的都招讨使。", "citation": "卷270·贞明三年（917）·zztj-v270-y0917-p013·原文件第18行", "note": "原文：蜀主以刘知俊为都招讨使，诸将皆旧功臣，多不用其命，且疾之，故无成功。；核对说明：原文称谓与既有姓名合并；原文摘录保留底本字形。"